--region import
---@type SDKService
local SDKService = import('Game.Entry.SDKService')
---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
--endregion import

--region define
local goodsConfMgr = GoodsConfMgr:GetInstance()
local KTool = CS.Engine.Lib.KTool
local XLuaUtils = CS.Engine.Lib.XLuaUtils
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaMall/OverseaMallChargeItem.prefab
---@class OverseaStoreTopUpCell
---@field Env                           	OverseaStoreTopUpCell                   
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Discount                      	UnityEngine.RectTransform               
---@field TextTitle                     	UnityEngine.RectTransform               
---@field DiamondIcon                   	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
---@field TextNumber                    	UnityEngine.RectTransform               
---@field ImgGoodsIcon                  	UnityEngine.RectTransform               
---@field Charge                        	TMPro.TextMeshProUGUI                   
---@field DescImgIcon                   	UnityEngine.RectTransform               
---@field Desc                          	UnityEngine.UI.Text                     
---@field Num                           	TMPro.TextMeshProUGUI                   
---@field Image                         	UnityEngine.RectTransform               
local OverseaStoreTopUpCell = Class("OverseaStoreTopUpCell")

--region lifecycle
function OverseaStoreTopUpCell:__init()
    self.data = nil
end

function OverseaStoreTopUpCell:__delete()
    self.data = nil
    
end

function OverseaStoreTopUpCell:Awake()
    KTool.SetActive(self.Discount, true)
    SetButtonAction(self.Root, Bind(self, self.OnClickAction))
end
--endregion lifecycle

--region handler
function OverseaStoreTopUpCell:OnClickAction()
    xRecord.record("5-014", string.format('click_recharge_%d', checkInt(self.data.productId)))
    local description  = self.Desc.text
    SDKService:GetInstance():PayMoney({
        productId = self.data.productId,
        channelProductId = self.data.channelProductId,
        productDesc = self.data.payPoint .. localize("猫眼石"),
        payAmount = checkNumber(self.data.price),
        data = self.data
    })
end
--endregion handler

--region public
---@param data OverseaStoreHomeDojo.Product
---@param index number
function OverseaStoreTopUpCell:RefreshState(data, index)
    self.data = data
    local goodsId = checkNumber(data.icon) == 0 and data.goodsId or checkNumber(data.icon)
    local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
    CfUtils.FillImage(self.DiamondIcon, goodsVo.photoPath)
    CfUtils.FillImage(self.Image, self:GetBgPath(index), false)
    -- 直接是真实价格
    local num = data.price
    if checkInt(data.payPoint) > 0 then
        local pointGoodsVo = goodsConfMgr:GetGoodsVoById(Constants.Currency.CumulativeScore)
		if pointGoodsVo.name ~= nil then
			CfUtils.FillText(self.Desc, pointGoodsVo.name .. '+' .. data.payPoint)
		else
			CfUtils.FillText(self.Desc, '+' .. data.payPoint)
		end
		CfUtils.FillImage(self.DescImgIcon, pointGoodsVo.photoPath)
        CfUtils.SetActive(self.Desc, true)
    else
        CfUtils.SetActive(self.Desc, false)
    end
    ---TMP字体没有中文，使用大A替换
    -- self.Charge.text =  string.format("A%d", checkNumber(num))
    local windowsPriceId =  CfUtils.GetWindowsPriceId(data)
    if CfUtils.isTH() and data.localePrice then
        CfUtils.FillText(self.Charge,string.format('<size=%d>%s</size>%s', 30, data.localeCurrencyCode, data.localePrice))
    else
        CfUtils.FillText(self.Charge,CfUtils.GetCustomDisplayPrice(windowsPriceId , data.channelProductId, 30))
    end
    self.Num.text = tostring(data.num)
    
    if checkInt(data.isFirst) == 1 then
        KTool.SetActive(self.TextNumber, true)
        KTool.SetActive(self.Discount, true)
        local vo = goodsConfMgr:GetInstance():GetGoodsVoById(data.extraGoodsId)
        CfUtils.FillImage(self.ImgGoodsIcon, vo.photoPath)
        CfUtils.FillText(self.TextNumber, " +" .. data.firstExtraNum)
    else
        KTool.SetActive(self.TextNumber, false)
        KTool.SetActive(self.Discount, false)
    end
end
--endregion public

function OverseaStoreTopUpCell:GetBgPath(index)
    return string.format(OverseaStoreConstants.ImgPath.TopUpDiamondIcon, index)
end

return OverseaStoreTopUpCell